// Zero-dependency bundler — concatenate the ESM src modules into a single
// self-contained file for GCU siblings to vendor / inline. Two outputs:
//
//   dist/capsule.js         ESM:  export { … }            (= @gcu/capsule/bundled)
//   dist/capsule.global.js  IIFE: globalThis.gcuCapsule   (classic-<script> inlining)
//
// The src modules have no external imports and no top-level name collisions, so
// a simple strip-local-imports + hoist-index-exports concatenation is sound (and
// guarded: test/bundle.test.js round-trips the bundle, and `--check` fails CI if
// the committed output drifts from source). Usage:
//
//   node build/bundle.js            write dist/
//   node build/bundle.js --check    exit 1 if committed dist/ is stale

import { readFileSync, writeFileSync } from 'node:fs';

const root = new URL('../', import.meta.url);
const read = p => readFileSync(new URL(p, root), 'utf8');

// Dependency order: each module's local imports appear above it.
const MODULES = [
  'src/codecs.js',
  'src/loaders/_fetch.js',
  'src/loaders/inline.js',
  'src/loaders/url.js',
  'src/loaders/gh.js',
  'src/loaders/gist.js',
  'src/loaders/zenodo.js',
  'src/loaders/doi.js',
  'src/loaders/rentry.js',
  'src/encode.js',
  'src/dispatcher.js',
  'src/share.js',
  'src/index.js',   // public API lives here — the only module we collect exports from
];

const exportNames = new Set();

const bracesToNames = s => s.split(',').map(x => x.trim()).filter(Boolean)
  .map(x => { const m = x.split(/\s+as\s+/); return (m[1] || m[0]).trim(); });

// Strip a module down to plain top-level declarations. `collect` (index.js only)
// gathers the public export names; other modules just lose their `export`/`import`
// framing so their symbols join the shared scope.
function strip(src, collect) {
  let s = src.replace(/export\s*\{([\s\S]*?)\}\s*(?:from\s*['"][^'"]+['"])?\s*;/g,
    (_, names) => { if (collect) bracesToNames(names).forEach(n => exportNames.add(n)); return ''; });
  s = s.replace(/^import\b[\s\S]*?;/gm, '');
  s = s.replace(/export\s+(async\s+function|function|const|let|var|class)\s+([A-Za-z_$][\w$]*)/g,
    (_, kw, name) => { if (collect) exportNames.add(name); return `${kw} ${name}`; });
  return s.replace(/\n{3,}/g, '\n\n').trim();
}

function build() {
  const body = MODULES.map(p => `// ===== ${p} ${'='.repeat(Math.max(2, 64 - p.length))}\n`
    + strip(read(p), p === 'src/index.js')).join('\n\n');

  const names = [...exportNames].sort();
  const list = names.map(n => '  ' + n).join(',\n');
  const header =
`// @gcu/capsule — bundled single-file build.
// GENERATED by build/bundle.js from src/ — DO NOT EDIT BY HAND.
// Regenerate: npm run build   ·   verify: npm run build:check
// MIT © Geoscientific Chaos Union. Spec: SPEC-capsule.md (CC0).
`;

  const esm = `${header}\n${body}\n\nexport {\n${list},\n};\n`;
  const glob = `${header}// Sets globalThis.gcuCapsule = { …public API }.\n`
    + `(() => {\n${body}\n\nglobalThis.gcuCapsule = {\n${list},\n};\n})();\n`;
  return { esm, glob };
}

const ESM_PATH = 'dist/capsule.js';
const GLOBAL_PATH = 'dist/capsule.global.js';
const { esm, glob } = build();
const check = process.argv.includes('--check');

if (check) {
  let stale = [];
  for (const [p, want] of [[ESM_PATH, esm], [GLOBAL_PATH, glob]]) {
    let have = '';
    try { have = read(p); } catch { have = null; }
    if (have !== want) stale.push(p);
  }
  if (stale.length) {
    console.error('Bundle out of date — run `npm run build`:\n  ' + stale.join('\n  '));
    process.exit(1);
  }
  console.log('Bundle up to date (' + exportNames.size + ' exports).');
} else {
  writeFileSync(new URL(ESM_PATH, root), esm);
  writeFileSync(new URL(GLOBAL_PATH, root), glob);
  console.log(`Wrote ${ESM_PATH} + ${GLOBAL_PATH} (${exportNames.size} exports, ${MODULES.length} modules).`);
}
